// Some portions generated by Codex
package org.eclipse.rdf4j.query;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.Test;

class QueryOperationDeadlineTest {

	@Test
	void remainingTimeUsesMonotonicClock() {
		AtomicLong nanoTime = new AtomicLong(100);
		QueryOperationDeadline deadline = QueryOperationDeadline.after(20, TimeUnit.NANOSECONDS, nanoTime::get);

		assertThat(deadline.remainingNanos()).isEqualTo(20);
		nanoTime.set(119);
		assertThat(deadline.remainingNanos()).isOne();
		assertThat(deadline.isExpired()).isFalse();
		nanoTime.set(120);
		assertThat(deadline.remainingNanos()).isZero();
		assertThat(deadline.isExpired()).isTrue();
		assertThatThrownBy(deadline::throwIfExpired)
				.isInstanceOf(QueryInterruptedException.class)
				.hasMessage("Query evaluation took too long");
	}

	@Test
	void deadlineCreationSaturatesInsteadOfWrapping() {
		AtomicLong nanoTime = new AtomicLong(Long.MAX_VALUE - 5);
		QueryOperationDeadline deadline = QueryOperationDeadline.after(10, TimeUnit.NANOSECONDS, nanoTime::get);

		assertThat(deadline.deadlineNanos()).isEqualTo(Long.MAX_VALUE);
		assertThat(deadline.remainingNanos()).isEqualTo(10);
		nanoTime.set(Long.MIN_VALUE + 3);
		assertThat(deadline.remainingNanos()).isOne();
		nanoTime.set(Long.MIN_VALUE + 4);
		assertThat(deadline.remainingNanos()).isZero();
		assertThat(deadline.isExpired()).isTrue();
	}

	@Test
	void invalidCloseOrderDoesNotMakeTheOuterScopeUncloseable() throws InterruptedException {
		AtomicReference<Throwable> failure = new AtomicReference<>();
		Thread thread = new Thread(() -> {
			try {
				QueryOperationDeadline outerDeadline = QueryOperationDeadline.after(2, TimeUnit.SECONDS);
				QueryOperationDeadline innerDeadline = QueryOperationDeadline.after(1, TimeUnit.SECONDS);
				QueryOperationContext.Scope outer = QueryOperationContext.open(outerDeadline);
				QueryOperationContext.Scope inner = QueryOperationContext.open(innerDeadline);

				assertThatThrownBy(outer::close)
						.isInstanceOf(IllegalStateException.class)
						.hasMessage("Query operation scopes must be closed in lexical order");
				inner.close();
				outer.close();
				assertThat(QueryOperationContext.getDeadline()).isEmpty();
			} catch (Throwable throwable) {
				failure.set(throwable);
			}
		}, "query-operation-context-close-test");

		thread.start();
		thread.join();

		assertThat(failure.get()).isNull();
	}

	@Test
	void nestedScopesUseEarliestDeadlineAndRestoreTheOuterScope() {
		AtomicLong nanoTime = new AtomicLong(100);
		QueryOperationDeadline outer = QueryOperationDeadline.after(30, TimeUnit.NANOSECONDS, nanoTime::get);
		QueryOperationDeadline later = QueryOperationDeadline.after(60, TimeUnit.NANOSECONDS, nanoTime::get);
		QueryOperationDeadline earlier = QueryOperationDeadline.after(10, TimeUnit.NANOSECONDS, nanoTime::get);

		assertThat(QueryOperationContext.getDeadline()).isEmpty();
		try (QueryOperationContext.Scope ignored = QueryOperationContext.open(outer)) {
			assertThat(QueryOperationContext.getDeadline()).containsSame(outer);
			try (QueryOperationContext.Scope nested = QueryOperationContext.open(later)) {
				assertThat(nested.getDeadline()).isSameAs(outer);
				assertThat(QueryOperationContext.getDeadline()).containsSame(outer);
			}
			try (QueryOperationContext.Scope nested = QueryOperationContext.open(earlier)) {
				assertThat(nested.getDeadline()).isSameAs(earlier);
				assertThat(QueryOperationContext.getDeadline()).containsSame(earlier);
			}
			assertThat(QueryOperationContext.getDeadline()).containsSame(outer);
		}
		assertThat(QueryOperationContext.getDeadline()).isEmpty();
	}
}
